PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS team_aliases (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  alias TEXT NOT NULL,
  normalized_alias TEXT NOT NULL,
  source_url TEXT,
  created_at TEXT NOT NULL,
  PRIMARY KEY (team_id, normalized_alias)
);

CREATE TABLE IF NOT EXISTS player_aliases (
  team_id TEXT NOT NULL,
  api_player_id INTEGER NOT NULL,
  alias TEXT NOT NULL,
  normalized_alias TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (team_id, api_player_id, normalized_alias),
  FOREIGN KEY (team_id, api_player_id) REFERENCES squad_players(team_id, api_player_id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_team_aliases_normalized ON team_aliases(normalized_alias);
CREATE INDEX IF NOT EXISTS idx_player_aliases_normalized ON player_aliases(normalized_alias);

